-- 32: PRE-FLIGHT for the website migration 20261116100000_bottle_signs. Read-only.
-- One result set. Rows 1 to 4 must say ok = true (what the migration builds on is there, and none of its names is taken). Any later row is information only (it never blocks).
select * from (
  select 1 as n, 'the functions this builds on exist' as check_name,
         (to_regprocedure('public.require_venue_editor(uuid)') is not null and to_regprocedure('public.venue_setup_log(text, text, uuid, uuid, jsonb)') is not null and to_regprocedure('public.desk_booking_level(uuid)') is not null and to_regprocedure('public.desk_log(text, text, uuid, jsonb)') is not null and to_regprocedure('public.booking_venue(uuid)') is not null and to_regprocedure('public.setup_only_keys(jsonb, text[])') is not null and to_regprocedure('public.setup_text(jsonb, text, text, int)') is not null and to_regprocedure('public.can_access_venue(uuid, text[])') is not null) as ok,
         concat_ws(', ', case when to_regprocedure('public.require_venue_editor(uuid)') is null then 'public.require_venue_editor missing' end, case when to_regprocedure('public.venue_setup_log(text, text, uuid, uuid, jsonb)') is null then 'public.venue_setup_log missing' end, case when to_regprocedure('public.desk_booking_level(uuid)') is null then 'public.desk_booking_level missing' end, case when to_regprocedure('public.desk_log(text, text, uuid, jsonb)') is null then 'public.desk_log missing' end, case when to_regprocedure('public.booking_venue(uuid)') is null then 'public.booking_venue missing' end, case when to_regprocedure('public.setup_only_keys(jsonb, text[])') is null then 'public.setup_only_keys missing' end, case when to_regprocedure('public.setup_text(jsonb, text, text, int)') is null then 'public.setup_text missing' end, case when to_regprocedure('public.can_access_venue(uuid, text[])') is null then 'public.can_access_venue missing' end) as detail
  union all
  select 2, 'the tables and columns this builds on exist',
         (to_regclass('public.site_bottles') is not null and to_regclass('public.site_table_booking_bottles') is not null and to_regclass('public.site_table_bookings') is not null and to_regclass('public.site_venues') is not null and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_venues' and column_name = 'id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_bottles' and column_name = 'venue_id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'booking_id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'bottle_id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'service_status') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'cancelled_at') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_bookings' and column_name = 'venue_id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_bookings' and column_name = 'status') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_bookings' and column_name = 'reconciled_at')),
         'site_bottles.venue_id, site_table_booking_bottles.booking_id, site_table_booking_bottles.bottle_id, site_table_booking_bottles.cancelled_at, site_table_booking_bottles.service_status, site_table_bookings.reconciled_at, site_table_bookings.status, site_table_bookings.venue_id, site_venues.id'
  union all
  select 3, 'none of the new names is taken (8 functions, 0 tables, 10 columns, 1 triggers)',
         (not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate'])) and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_venues' and column_name = 'sign_mode') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_venues' and column_name = 'sign_review') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_bottles' and column_name = 'sign_eligible') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_text') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_status') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_set_by') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_set_at') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_reviewed_by') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_reviewed_at') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_review_note') and not exists (select 1 from pg_trigger g where g.tgname = 'site_table_booking_bottles_sign_gate')),
         concat_ws(', ', coalesce((select string_agg(p.proname, ', ') from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate'])), ''), case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_venues' and column_name = 'sign_mode') then 'site_venues.sign_mode exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_venues' and column_name = 'sign_review') then 'site_venues.sign_review exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_bottles' and column_name = 'sign_eligible') then 'site_bottles.sign_eligible exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_text') then 'site_table_booking_bottles.sign_text exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_status') then 'site_table_booking_bottles.sign_status exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_set_by') then 'site_table_booking_bottles.sign_set_by exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_set_at') then 'site_table_booking_bottles.sign_set_at exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_reviewed_by') then 'site_table_booking_bottles.sign_reviewed_by exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_reviewed_at') then 'site_table_booking_bottles.sign_reviewed_at exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'sign_review_note') then 'site_table_booking_bottles.sign_review_note exists' else '' end)
  union all
  select 4, 'the roles exist (the functions are granted to authenticated and service_role and taken from anon)',
         exists (select 1 from pg_roles where rolname = 'service_role') and exists (select 1 from pg_roles where rolname = 'authenticated') and exists (select 1 from pg_roles where rolname = 'anon'),
         'service_role, authenticated, anon'
  union all
  select 5, 'INFORMATION: bottle lines and clubs the new columns will sit on (all start with no sign and signs off)', true, (select count(*)::text from public.site_table_booking_bottles) || ' bottle lines, ' || (select count(*)::text from public.site_venues) || ' clubs, ' || (select count(*)::text from public.site_bottles) || ' menu bottles'
) r order by n;
